import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  fmtNum,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';

// ═══════════════════════════════════════════════════════════════════════════════
// Types & constants — compact layout so fitToView keeps the block readable.
// ═══════════════════════════════════════════════════════════════════════════════

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e8f5e9', stroke: '#4caf50' },
  norm: { fill: '#fff8e1', stroke: '#f9a825' },
  attn: { fill: '#e3f2fd', stroke: '#1976d2' },
  mlp: { fill: '#fff3e0', stroke: '#f57c00' },
  weight: { fill: '#f1f5f9', stroke: '#64748b' },
  score: { fill: '#fce4ec', stroke: '#c2185b' },
  softmax: { fill: '#fff8e1', stroke: '#f9a825' },
  output: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  residual: { fill: '#e8f5e9', stroke: '#4caf50' },
  mul: { fill: '#fff3e0', stroke: '#f57c00' },
  inset: { fill: '#f8fafc', stroke: '#cbd5e1' },
  text: 'var(--text)',
  muted: 'var(--text-muted)',
};

const STEP_GROUPS = {
  input: 'step-tb-input',
  norm1: 'step-tb-norm1',
  attn: 'step-tb-attn',
  res1: 'step-tb-res1',
  norm2: 'step-tb-norm2',
  mlp: 'step-tb-mlp',
  res2: 'step-tb-res2',
  output: 'step-tb-output',
};

const BOX_H = 52;
const BOX_W = 920;
const MAT_H = 60;
const VEC_H = 28;
const VEC_W = 120;
const WEIGHT_W = 96;
const WEIGHT_H = 70;
const SEQ_W = 140;
const GROUP_GAP = 80;
const BOX_TO_ROW_GAP = 44;
const VERTICAL_ARROW_LEN = 80;
const ROW_EQ_GAP = 44;
const RESIDUAL_OFFSET = 300;

const ALPHA = 2.0; // DeepNorm residual scaling factor

interface BlockStep extends StepInfo {}

interface RenderResult {
  steps: BlockStep[];
  y: number;
}

interface BlockParams {
  dModel: number;
  nHeads: number;
  seqLen: number;
  dFf: number;
  activation: string;
  normType: string;
  variant: string;
  attentionType: string;
  mlpVariant: string;
  dHead: number;
  nKVHeads: number;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Low-level helpers
// ═══════════════════════════════════════════════════════════════════════════════

function lbl(
  g: Gsel,
  x: number,
  y: number,
  text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function arrowH(g: Gsel, x1: number, x2: number, y: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x1, y, x2, y, { color });
}

function startGroup(g: Gsel, className: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${className}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel,
  cx: number,
  y: number,
  stepNum: number,
  title: string,
  formula: string,
  fill: string,
  stroke: string,
  width = BOX_W
): number {
  const grp = g.append('g');
  grp
    .append('rect')
    .attr('x', cx - width / 2)
    .attr('y', y)
    .attr('width', width)
    .attr('height', BOX_H)
    .attr('rx', 8)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);

  grp.append('circle')
    .attr('cx', cx - width / 2 + 22)
    .attr('cy', y + BOX_H / 2)
    .attr('r', 14)
    .attr('fill', stroke);
  lbl(grp, cx - width / 2 + 22, y + BOX_H / 2 + 1, String(stepNum), { size: 13, weight: '700', color: '#fff' });

  lbl(grp, cx - width / 2 + 44, y + BOX_H / 2 - 1, title, {
    size: 15,
    weight: '600',
    color: 'var(--text)',
    anchor: 'start',
  });
  lbl(grp, cx + width / 2 - 14, y + BOX_H / 2 - 1, formula, {
    size: 11,
    color: 'var(--text-muted)',
    font: 'monospace',
    anchor: 'end',
  });
  return y + BOX_H;
}

function opCircle(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle')
    .attr('cx', cx)
    .attr('cy', cy)
    .attr('r', 14)
    .attr('fill', '#fff')
    .attr('stroke', color)
    .attr('stroke-width', 2);
  lbl(g, cx, cy + 1, text, { size: 12, weight: '700', color });
}

function hexWithAlpha(hex: string, alpha: number): string {
  const v = hex.replace('#', '');
  const bigint = parseInt(v, 16);
  const r = (bigint >> 16) & 255;
  const g = (bigint >> 8) & 255;
  const b = bigint & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Matrix helpers
// ═══════════════════════════════════════════════════════════════════════════════

function drawSeqMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.input.fill,
  stroke = COLORS.input.stroke
): void {
  drawMatrixBlock(g as Sel, x - SEQ_W / 2, cy - MAT_H / 2, {
    width: SEQ_W,
    height: MAT_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 5,
    dimTop: 'S',
    dimRight: 'D',
  });
}

function drawWeightMatrix(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill = COLORS.weight.fill,
  stroke = COLORS.weight.stroke,
  width = WEIGHT_W,
  height = WEIGHT_H
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - height / 2, {
    width,
    height,
    label,
    sublabel,
    fill,
    stroke,
    cols: 5,
    rows: 5,
  });
}

function drawSmallVector(
  g: Gsel,
  x: number,
  cy: number,
  label: string,
  sublabel: string,
  fill: string,
  stroke: string,
  width = VEC_W
): void {
  drawMatrixBlock(g as Sel, x - width / 2, cy - VEC_H / 2, {
    width,
    height: VEC_H,
    label,
    sublabel,
    fill,
    stroke,
    cols: 8,
    rows: 1,
  });
}

function drawBadge(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string): void {
  const badgeW = Math.max(80, text.length * 7 + 14);
  const badgeH = VEC_H;
  g.append('rect')
    .attr('x', cx - badgeW / 2)
    .attr('y', cy - badgeH / 2)
    .attr('width', badgeW)
    .attr('height', badgeH)
    .attr('rx', 6)
    .attr('fill', fill)
    .attr('stroke', stroke)
    .attr('stroke-width', 1.5);
  lbl(g, cx, cy, text, { size: 10, weight: '600', color: stroke });
}

// ═══════════════════════════════════════════════════════════════════════════════
// Residual path
// ═══════════════════════════════════════════════════════════════════════════════

function drawResidualPath(
  g: Gsel,
  startX: number,
  startY: number,
  endX: number,
  endY: number,
  options: { color?: string; label?: string; scaleAlpha?: boolean; side?: 'left' | 'right' } = {}
): void {
  const { color = COLORS.residual.stroke, label = 'residual', scaleAlpha = false, side = 'right' } = options;
  const farX = side === 'right' ? CX + RESIDUAL_OFFSET : CX - RESIDUAL_OFFSET;
  const path = side === 'right'
    ? `M ${startX},${startY} L ${farX},${startY} L ${farX},${endY} L ${endX},${endY}`
    : `M ${startX},${startY} L ${farX},${startY} L ${farX},${endY} L ${endX},${endY}`;
  g.append('path')
    .attr('d', path)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('stroke-dasharray', '5,3')
    .attr('opacity', 0.75);
  lbl(g, farX - 8, (startY + endY) / 2, label, { size: 10, color, anchor: 'end' });

  if (scaleAlpha) {
    const badgeW = 44;
    const badgeH = 22;
    g.append('rect')
      .attr('x', farX - badgeW / 2)
      .attr('y', endY - badgeH / 2 - 18)
      .attr('width', badgeW)
      .attr('height', badgeH)
      .attr('rx', 4)
      .attr('fill', '#fff')
      .attr('stroke', color)
      .attr('stroke-width', 1.5);
    lbl(g, farX, endY - 17, `×${ALPHA}`, { size: 10, weight: '600', color });
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter summary
// ═══════════════════════════════════════════════════════════════════════════════

function drawParamSummary(g: Gsel, cx: number, y: number, p: BlockParams): number {
  const SUM_W = 960;
  const SUM_H = 92;
  const grp = g.append('g').attr('transform', `translate(${cx - SUM_W / 2}, ${y})`);
  grp.append('rect')
    .attr('width', SUM_W)
    .attr('height', SUM_H)
    .attr('rx', 8)
    .attr('fill', 'var(--surface)')
    .attr('stroke', 'var(--border)')
    .attr('stroke-width', 1);
  lbl(grp, 14, 18, 'Parameters →', { size: 10, weight: '700', color: 'var(--text-muted)' });

  const items = [
    { label: `d_model=${p.dModel}`, meta: 'hidden', color: '#4caf50' },
    { label: `n_heads=${p.nHeads}`, meta: 'heads', color: '#1976d2' },
    { label: `seq_len=${p.seqLen}`, meta: 'tokens', color: '#7b1fa2' },
    { label: `d_ff=${p.dFf}`, meta: 'FFN', color: '#f57c00' },
    { label: `norm=${p.normType}`, meta: 'norm', color: '#f9a825' },
    { label: `attn=${p.attentionType.toUpperCase()}`, meta: 'attention', color: '#1565c0' },
    { label: `FFN=${p.mlpVariant}`, meta: 'MLP', color: '#e65100' },
    { label: `block=${p.variant}`, meta: 'arch', color: '#009688' },
  ];
  const cols = 4;
  const itemW = 236;
  const itemH = 34;
  const startX = 8;
  const startY = 26;
  items.forEach((item, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const px = startX + col * itemW;
    const py = startY + row * itemH;
    grp.append('rect')
      .attr('x', px)
      .attr('y', py)
      .attr('width', itemW - 8)
      .attr('height', itemH - 4)
      .attr('rx', 6)
      .attr('fill', hexWithAlpha(item.color, 0.08))
      .attr('stroke', item.color)
      .attr('stroke-width', 1);
    lbl(grp, px + 8, py + 13, item.label, {
      size: 10,
      weight: '600',
      color: item.color,
      font: 'monospace',
      anchor: 'start',
    });
    lbl(grp, px + 8, py + 24, `→ ${item.meta}`, { size: 8, color: item.color, anchor: 'start' });
  });
  return y + SUM_H + 14;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Input / Output steps
// ═══════════════════════════════════════════════════════════════════════════════

function drawInputStep(g: Gsel, cx: number, y: number, stepId: number, p: BlockParams): number {
  const grp = startGroup(g, STEP_GROUPS.input, stepId);
  const headerBottom = stepHeader(
    grp,
    cx,
    y,
    stepId,
    'Input hidden states',
    `x ∈ ℝ^(B×S×${p.dModel})`,
    COLORS.input.fill,
    COLORS.input.stroke
  );
  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, 'x', `[B, S, ${p.dModel}]`, COLORS.input.fill, COLORS.input.stroke);
  lbl(grp, cx, cy + MAT_H / 2 + 16, 'one hidden vector per token position', { size: 10, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

function drawOutputStep(g: Gsel, cx: number, y: number, stepId: number, p: BlockParams): number {
  const grp = startGroup(g, STEP_GROUPS.output, stepId);
  const headerBottom = stepHeader(
    grp,
    cx,
    y,
    stepId,
    'Output hidden states',
    `out ∈ ℝ^(B×S×${p.dModel})`,
    COLORS.output.fill,
    COLORS.output.stroke
  );
  const cy = headerBottom + BOX_TO_ROW_GAP + MAT_H / 2;
  drawSeqMatrix(grp, cx, cy, 'out', `[B, S, ${p.dModel}]`, COLORS.output.fill, COLORS.output.stroke);
  lbl(grp, cx, cy + MAT_H / 2 + 16, 'passed to the next block (or final LM head)', { size: 10, color: COLORS.muted });
  return cy + MAT_H / 2 + 30;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Attention sub-layer — compact horizontal flow
// ═══════════════════════════════════════════════════════════════════════════════

interface SubLayerResult {
  bottom: number;
  outputCy: number;
  startY: number;
}

function drawAttentionSubLayer(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  withNorm: boolean,
  residualStartY: number,
  headerWidth = BOX_W,
  inputLabel = 'x'
): SubLayerResult {
  const dModel = p.dModel;
  const grp = startGroup(g, STEP_GROUPS.attn, stepId);
  const title = withNorm ? `${p.normType} + Attention` : 'Attention';
  const formula = withNorm ? 'attn_out = MHA(Norm(x))' : 'attn_out = MHA(x)';
  const headerBottom = stepHeader(grp, cx, y, stepId, title, formula, COLORS.attn.fill, COLORS.attn.stroke, headerWidth);

  let cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;

  // Optional input norm badge + x_norm vector on same row
  if (withNorm) {
    const normBadgeX = cx - 150;
    drawBadge(grp, normBadgeX, cy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
    drawSmallVector(grp, cx, cy, 'x_norm', `[B, S, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 140);
    arrowH(grp, normBadgeX + 43, cx - 65, cy, COLORS.norm.stroke);
  } else {
    drawSmallVector(grp, cx, cy, inputLabel, `[B, S, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 140);
  }
  const inputBottom = cy + VEC_H / 2;
  cy += VEC_H / 2 + VERTICAL_ARROW_LEN;

  // QKV projections side by side
  const isGQA = p.attentionType === 'gqa';
  const isMQA = p.attentionType === 'mqa';
  const kvOutDim = p.dHead * p.nKVHeads;
  const kvShape = isMQA ? `[D, ${p.dHead}]` : `[D, ${kvOutDim}]`;
  const qShape = `[D, ${dModel}]`;

  const qx = cx - 220;
  const kx = cx;
  const vx = cx + 220;

  drawWeightMatrix(grp, qx, cy, 'W_q', qShape, COLORS.weight.fill, COLORS.weight.stroke);
  drawWeightMatrix(grp, kx, cy, 'W_k', kvShape, COLORS.weight.fill, COLORS.weight.stroke);
  drawWeightMatrix(grp, vx, cy, 'W_v', kvShape, COLORS.weight.fill, COLORS.weight.stroke);

  // Fan-out arrows from x_norm/x (at cx) to each weight matrix
  drawArrow(grp as Sel, cx, inputBottom, qx, cy - WEIGHT_H / 2, { color: COLORS.attn.stroke });
  arrowDown(grp, kx, inputBottom, cy - WEIGHT_H / 2, COLORS.attn.stroke);
  drawArrow(grp as Sel, cx, inputBottom, vx, cy - WEIGHT_H / 2, { color: COLORS.attn.stroke });

  // Q/K/V output vectors
  const outY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, qx, outY, 'Q', `[B, S, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke);
  drawSmallVector(grp, kx, outY, 'K', `[B, S, ${kvOutDim}]`, COLORS.attn.fill, COLORS.attn.stroke);
  drawSmallVector(grp, vx, outY, 'V', `[B, S, ${kvOutDim}]`, COLORS.attn.fill, COLORS.attn.stroke);
  arrowDown(grp, qx, cy + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);
  arrowDown(grp, kx, cy + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);
  arrowDown(grp, vx, cy + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);

  // Head split / reshape note (placed beside V so it does not cross the K arrow)
  const headText = isMQA
    ? `${p.nHeads} Q heads share 1 K/V head (MQA)`
    : isGQA
    ? `${p.nHeads} Q heads share ${p.nKVHeads} K/V heads (GQA)`
    : `${p.nHeads} heads × d_head=${p.dHead}`;
  lbl(grp, vx + 78, outY, `reshape → ${headText}`, { size: 11, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  // ── Vertical attention computation ──────────────────────────────────────────
  // Row 1: scores
  let compCy = outY + VEC_H + ROW_EQ_GAP + VEC_H / 2;
  const scoresTop = compCy - VEC_H / 2;
  drawSmallVector(grp, cx, compCy, 'scores', `[B, n_h, S, S]`, COLORS.score.fill, COLORS.score.stroke, 120);
  lbl(grp, cx + 68, compCy, '= Q @ K^T / √d_h', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  // Q arrow: diagonal from Q vector to scores box
  drawArrow(grp as Sel, qx, outY + VEC_H / 2, cx - 58, scoresTop - 2, { color: COLORS.attn.stroke });
  lbl(grp, qx + 10, outY + VEC_H / 2 + 24, 'Q', { size: 9, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });
  // K diagonal: go down to scores row level, then label
  drawArrow(grp as Sel, kx, outY + VEC_H / 2, cx + 58, scoresTop - 2, { color: COLORS.attn.stroke });
  lbl(grp, kx + 10, outY + VEC_H / 2 + 24, 'K', { size: 9, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });
  let prevBottom = compCy + VEC_H / 2;

  // Row 2: softmax badge
  compCy = prevBottom + ROW_EQ_GAP + VEC_H / 2;
  drawBadge(grp, cx, compCy, 'softmax', COLORS.softmax.fill, COLORS.softmax.stroke);
  lbl(grp, cx + 48, compCy, 'causal mask + row-softmax', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  arrowDown(grp, cx, prevBottom, compCy - VEC_H / 2, COLORS.score.stroke);
  prevBottom = compCy + VEC_H / 2;

  // Row 3: A (attention weights)
  compCy = prevBottom + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, compCy, 'A', `[B, n_h, S, S]`, COLORS.softmax.fill, COLORS.softmax.stroke, 110);
  lbl(grp, cx + 58, compCy, '(attention weights ∈ [0,1])', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  arrowDown(grp, cx, prevBottom, compCy - VEC_H / 2, COLORS.softmax.stroke);
  prevBottom = compCy + VEC_H / 2;

  // Row 4: context = A @ V
  compCy = prevBottom + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, compCy, 'context', `[B, n_h, S, d_h]`, COLORS.attn.fill, COLORS.attn.stroke, 140);
  lbl(grp, cx + 78, compCy, '= A @ V', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  arrowDown(grp, cx, prevBottom, compCy - VEC_H / 2, COLORS.softmax.stroke);
  // V diagonal: from V vector to context node
  drawArrow(grp as Sel, vx, outY + VEC_H / 2, cx + 68, compCy - VEC_H / 2 - 2, { color: COLORS.attn.stroke });
  lbl(grp, vx + 10, outY + VEC_H / 2 + 24, 'V', { size: 9, weight: '600', color: COLORS.attn.stroke, font: 'monospace' });
  prevBottom = compCy + VEC_H / 2;

  // Row 5: W_o output projection
  compCy = prevBottom + ROW_EQ_GAP + WEIGHT_H / 2;
  drawWeightMatrix(grp, cx, compCy, 'W_o', `[D, D]`, COLORS.weight.fill, COLORS.weight.stroke);
  lbl(grp, cx + WEIGHT_W / 2 + 10, compCy, 'output projection', { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  arrowDown(grp, cx, prevBottom, compCy - WEIGHT_H / 2, COLORS.attn.stroke);
  prevBottom = compCy + WEIGHT_H / 2;

  // Row 6: attn_out
  compCy = prevBottom + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, compCy, 'attn_out', `[B, S, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 130);
  lbl(grp, cx + 68, compCy, `∈ ℝ^(B×S×${dModel})`, { size: 10, color: COLORS.muted, font: 'monospace', anchor: 'start' });
  arrowDown(grp, cx, prevBottom, compCy - VEC_H / 2, COLORS.weight.stroke);

  return { bottom: compCy + VEC_H / 2 + 30, outputCy: compCy, startY: residualStartY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// MLP sub-layer — compact flow
// ═══════════════════════════════════════════════════════════════════════════════

function drawMlpSubLayer(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  p: BlockParams,
  withNorm: boolean,
  residualStartY: number,
  headerWidth = BOX_W,
  inputLabel = 'x'
): SubLayerResult {
  const dModel = p.dModel;
  const grp = startGroup(g, STEP_GROUPS.mlp, stepId);
  const title = withNorm ? `${p.normType} + ${p.mlpVariant.toUpperCase()} FFN` : `${p.mlpVariant.toUpperCase()} FFN`;
  const formula = withNorm ? 'mlp_out = MLP(Norm(x))' : 'mlp_out = MLP(x)';
  const headerBottom = stepHeader(grp, cx, y, stepId, title, formula, COLORS.mlp.fill, COLORS.mlp.stroke, headerWidth);

  let cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;

  // Optional input norm badge + x_norm vector on same row
  if (withNorm) {
    const normBadgeX = cx - 150;
    drawBadge(grp, normBadgeX, cy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
    drawSmallVector(grp, cx, cy, 'x_norm', `[B, S, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 140);
    arrowH(grp, normBadgeX + 43, cx - 65, cy, COLORS.norm.stroke);
  } else {
    drawSmallVector(grp, cx, cy, inputLabel, `[B, S, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 140);
  }
  const inputBottom = cy + VEC_H / 2;
  cy += VEC_H / 2 + VERTICAL_ARROW_LEN;

  const isGated = p.mlpVariant === 'swiglu' || p.mlpVariant === 'geglu';

  if (!isGated) {
    // Standard: x → W_up → up → activation → W_down → out
    drawWeightMatrix(grp, cx, cy, 'W_up', `[${p.dModel}, ${p.dFf}]`, COLORS.weight.fill, COLORS.weight.stroke);
    arrowDown(grp, cx, inputBottom, cy - WEIGHT_H / 2, COLORS.mlp.stroke);
    const upY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
    drawSmallVector(grp, cx, upY, 'up', `[B, S, ${p.dFf}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 120);
    arrowDown(grp, cx, cy + WEIGHT_H / 2, upY - VEC_H / 2, COLORS.weight.stroke);
    lbl(grp, cx + VEC_W / 2 + 10, upY, '× W_up', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

    const actY = upY + VEC_H / 2 + ROW_EQ_GAP;
    drawBadge(grp, cx, actY, p.activation, COLORS.mlp.fill, COLORS.mlp.stroke);

    const downWeightY = actY + VEC_H / 2 + ROW_EQ_GAP;
    drawWeightMatrix(grp, cx, downWeightY, 'W_down', `[${p.dFf}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke);
    const outY = downWeightY + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
    drawSmallVector(grp, cx, outY, 'mlp_out', `[B, S, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 130);
    arrowDown(grp, cx, downWeightY + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);
    lbl(grp, cx + VEC_W / 2 + 10, outY, '× W_down', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

    return { bottom: outY + VEC_H / 2 + 20, outputCy: outY, startY: residualStartY };
  }

  // Gated: SwiGLU / GeGLU — two-column flow with clear multiply step
  const gateAct = p.mlpVariant === 'swiglu' ? 'SiLU' : 'GELU';

  // W_gate / W_up side by side
  const gateX = cx - 150;
  const upX = cx + 150;
  drawWeightMatrix(grp, gateX, cy, 'W_gate', `[${p.dModel}, ${p.dFf}]`, COLORS.weight.fill, COLORS.weight.stroke);
  drawWeightMatrix(grp, upX, cy, 'W_up', `[${p.dModel}, ${p.dFf}]`, COLORS.weight.fill, COLORS.weight.stroke);
  arrowDown(grp, gateX, inputBottom, cy - WEIGHT_H / 2, COLORS.mlp.stroke);
  arrowDown(grp, upX, inputBottom, cy - WEIGHT_H / 2, COLORS.mlp.stroke);

  const projY = cy + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, gateX, projY, 'gate', `[B, S, ${p.dFf}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 110);
  drawSmallVector(grp, upX, projY, 'up', `[B, S, ${p.dFf}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 110);
  arrowDown(grp, gateX, cy + WEIGHT_H / 2, projY - VEC_H / 2, COLORS.weight.stroke);
  arrowDown(grp, upX, cy + WEIGHT_H / 2, projY - VEC_H / 2, COLORS.weight.stroke);

  const actY = projY + VEC_H / 2 + ROW_EQ_GAP;
  drawBadge(grp, gateX, actY, gateAct, COLORS.mlp.fill, COLORS.mlp.stroke);
  arrowDown(grp, gateX, projY + VEC_H / 2, actY - VEC_H / 2, COLORS.mlp.stroke);
  lbl(grp, upX, actY, 'pass through', { size: 9, color: COLORS.muted, font: 'monospace' });

  const mulCircleY = actY + VEC_H / 2 + ROW_EQ_GAP;
  opCircle(grp, cx, mulCircleY, '⊙', COLORS.mul.stroke);
  // gate → ⊙: from GELU badge down then diagonal to circle
  drawArrow(grp as Sel, gateX, actY + VEC_H / 2, cx - 16, mulCircleY, { color: COLORS.mlp.stroke });
  // up → ⊙: from up vector down then diagonal to circle
  drawArrow(grp as Sel, upX, projY + VEC_H / 2, cx + 16, mulCircleY, { color: COLORS.mlp.stroke });

  const mulY = mulCircleY + 14 + ROW_EQ_GAP / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, mulY, 'gated', `[B, S, ${p.dFf}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 130);
  arrowDown(grp, cx, mulCircleY + 14, mulY - VEC_H / 2, COLORS.mul.stroke);
  lbl(grp, cx + 78, mulY, 'gate ⊙ up', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  const downY = mulY + VEC_H / 2 + ROW_EQ_GAP;
  drawWeightMatrix(grp, cx, downY, 'W_down', `[${p.dFf}, ${dModel}]`, COLORS.weight.fill, COLORS.weight.stroke);
  const outY = downY + WEIGHT_H / 2 + VERTICAL_ARROW_LEN / 2 + VEC_H / 2;
  drawSmallVector(grp, cx, outY, 'mlp_out', `[B, S, ${dModel}]`, COLORS.mlp.fill, COLORS.mlp.stroke, 130);
  arrowDown(grp, cx, downY + WEIGHT_H / 2, outY - VEC_H / 2, COLORS.weight.stroke);
  lbl(grp, cx + VEC_W / 2 + 10, outY, '× W_down', { size: 9, color: COLORS.muted, font: 'monospace', anchor: 'start' });

  return { bottom: outY + VEC_H / 2 + 20, outputCy: outY, startY: residualStartY };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Residual add node — compact
// ═══════════════════════════════════════════════════════════════════════════════

function drawResidualAdd(
  g: Gsel,
  cx: number,
  y: number,
  stepId: number,
  groupName: string,
  formula: string,
  label: string,
  subLayer: SubLayerResult,
  dModel: number,
  options: { postNorm?: boolean; extraNorm?: string; scaleAlpha?: boolean } = {}
): number {
  const { postNorm = false, extraNorm, scaleAlpha = false } = options;
  const grp = startGroup(g, groupName, stepId);
  const headerBottom = stepHeader(grp, cx, y, stepId, label, formula, COLORS.residual.fill, COLORS.residual.stroke);

  const cy = headerBottom + BOX_TO_ROW_GAP + VEC_H / 2;

  // Optional extra norm before the add (sandwich-norm)
  if (extraNorm) {
    drawBadge(grp, cx, cy, extraNorm, COLORS.norm.fill, COLORS.norm.stroke);
    arrowDown(grp, cx, cy + VEC_H / 2, cy + VEC_H / 2 + VERTICAL_ARROW_LEN, COLORS.norm.stroke);
  }

  const addCy = extraNorm ? cy + VEC_H / 2 + VERTICAL_ARROW_LEN + VEC_H / 2 : cy;
  opCircle(grp, cx, addCy, '⊕', COLORS.residual.stroke);
  drawSmallVector(grp, cx - 80, addCy, 'sub_out', `[B, S, ${dModel}]`, COLORS.attn.fill, COLORS.attn.stroke, 90);
  // Sub-layer output arrives from above
  arrowDown(grp, cx, addCy - 42, addCy - 15, COLORS.attn.stroke);

  // Residual path from the source around the sub-layer
  const startX = cx + SEQ_W / 2 + 4;
  const endX = cx + 14;
  drawResidualPath(grp, startX, subLayer.startY, endX, addCy, { color: COLORS.residual.stroke, scaleAlpha });

  // Output after add
  let outCy = addCy + VEC_H / 2 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(grp, cx, outCy, 'residual_out', `[B, S, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke, 140);
  arrowDown(grp, cx, addCy + 14, outCy - VEC_H / 2, COLORS.residual.stroke);

  if (postNorm) {
    const normCy = outCy + VEC_H / 2 + ROW_EQ_GAP;
    drawBadge(grp, cx, normCy, extraNorm || 'LayerNorm', COLORS.norm.fill, COLORS.norm.stroke);
    outCy = normCy + VEC_H / 2 + ROW_EQ_GAP;
    drawSmallVector(grp, cx, outCy, 'normed_out', `[B, S, ${dModel}]`, COLORS.residual.fill, COLORS.residual.stroke, 140);
    arrowDown(grp, cx, normCy + VEC_H / 2, outCy - VEC_H / 2, COLORS.norm.stroke);
  }

  return outCy + VEC_H / 2 + 10;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Variant renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderPreNorm(g: Gsel, cx: number, y: number, p: BlockParams): RenderResult {
  const steps: BlockStep[] = [];

  const inputBottom = drawInputStep(g, cx, y, 1, p);
  steps.push(makeInputStep(1, p));
  y = inputBottom + GROUP_GAP;

  const attnStartY = inputBottom - 30;
  const attnResult = drawAttentionSubLayer(g, cx, y, 2, p, true, attnStartY);
  steps.push(makeNormStep(2, `${p.normType} (pre-attn)`, 'norm1', p));
  steps.push(makeAttnStep(3, p));
  y = attnResult.bottom + GROUP_GAP;

  const res1Bottom = drawResidualAdd(g, cx, y, 4, STEP_GROUPS.res1, 'x1 = x + attn_out', 'Residual Add 1', attnResult, p.dModel);
  steps.push(makeResStep(4, 1, p));
  y = res1Bottom + GROUP_GAP;

  const mlpStartY = res1Bottom - 10;
  const mlpResult = drawMlpSubLayer(g, cx, y, 5, p, true, mlpStartY);
  steps.push(makeNormStep(5, `${p.normType} (pre-FFN)`, 'norm2', p));
  steps.push(makeMlpStep(6, p));
  y = mlpResult.bottom + GROUP_GAP;

  const res2Bottom = drawResidualAdd(g, cx, y, 7, STEP_GROUPS.res2, 'out = x1 + mlp_out', 'Residual Add 2', mlpResult, p.dModel);
  steps.push(makeResStep(7, 2, p));
  y = res2Bottom + GROUP_GAP;

  const outputBottom = drawOutputStep(g, cx, y, 8, p);
  steps.push(makeOutputStep(8, p));

  return { steps, y: outputBottom };
}

function renderPostNorm(g: Gsel, cx: number, y: number, p: BlockParams): RenderResult {
  const steps: BlockStep[] = [];

  const inputBottom = drawInputStep(g, cx, y, 1, p);
  steps.push(makeInputStep(1, p));
  y = inputBottom + GROUP_GAP;

  const attnStartY = inputBottom - 30;
  const attnResult = drawAttentionSubLayer(g, cx, y, 2, p, false, attnStartY);
  steps.push(makeAttnStep(2, p));
  y = attnResult.bottom + GROUP_GAP;

  const res1Bottom = drawResidualAdd(g, cx, y, 3, STEP_GROUPS.res1, 'x1 = x + attn_out', 'Residual Add 1', attnResult, p.dModel, {
    postNorm: true,
    extraNorm: p.normType,
  });
  steps.push(makeResStep(3, 1, p));
  steps.push(makeNormStep(4, `${p.normType} (post-attn)`, 'norm1', p));
  y = res1Bottom + GROUP_GAP;

  const mlpStartY = res1Bottom - 30;
  const mlpResult = drawMlpSubLayer(g, cx, y, 5, p, false, mlpStartY);
  steps.push(makeMlpStep(5, p));
  y = mlpResult.bottom + GROUP_GAP;

  const res2Bottom = drawResidualAdd(g, cx, y, 6, STEP_GROUPS.res2, 'out = x1 + mlp_out', 'Residual Add 2', mlpResult, p.dModel, {
    postNorm: true,
    extraNorm: p.normType,
  });
  steps.push(makeResStep(6, 2, p));
  steps.push(makeNormStep(7, `${p.normType} (post-FFN)`, 'norm2', p));
  y = res2Bottom + GROUP_GAP;

  const outputBottom = drawOutputStep(g, cx, y, 8, p);
  steps.push(makeOutputStep(8, p));

  return { steps, y: outputBottom };
}

function renderParallel(g: Gsel, cx: number, y: number, p: BlockParams): RenderResult {
  const dModel = p.dModel;
  const steps: BlockStep[] = [];

  const inputBottom = drawInputStep(g, cx, y, 1, p);
  steps.push(makeInputStep(1, p));
  y = inputBottom + GROUP_GAP;

  // Single shared norm
  const normGrp = startGroup(g, STEP_GROUPS.norm1, 2);
  const normHeaderBottom = stepHeader(normGrp, cx, y, 2, `Shared ${p.normType}`, 'x_norm = Norm(x)', COLORS.norm.fill, COLORS.norm.stroke);
  const normCy = normHeaderBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  const normBadgeX = cx - 150;
  drawBadge(normGrp, normBadgeX, normCy, p.normType, COLORS.norm.fill, COLORS.norm.stroke);
  drawSmallVector(normGrp, cx, normCy, 'x_norm', `[B, S, ${dModel}]`, COLORS.norm.fill, COLORS.norm.stroke, 140);
  arrowH(normGrp, normBadgeX + 43, cx - 65, normCy, COLORS.norm.stroke);
  const normBottom = normCy + VEC_H / 2 + 10;
  steps.push(makeNormStep(2, `${p.normType} (shared)`, 'norm1', p));
  y = normBottom + GROUP_GAP;

  // Two columns: attention (left) and MLP (right)
  const colGap = 360;
  const leftCx = cx - colGap;
  const rightCx = cx + colGap;
  const branchTop = y;
  const subHeaderWidth = 460;

  // Input distribution arrows from norm output to both columns
  const distY = normCy + VEC_H / 2 + 10 + GROUP_GAP - 8;
  arrowH(g, cx - 70, leftCx, distY, COLORS.norm.stroke);
  arrowH(g, cx + 70, rightCx, distY, COLORS.norm.stroke);

  const attnResult = drawAttentionSubLayer(g, leftCx, branchTop, 3, p, false, normCy, subHeaderWidth, 'x_norm');
  steps.push(makeAttnStep(3, p));
  const mlpResult = drawMlpSubLayer(g, rightCx, branchTop, 4, p, false, normCy, subHeaderWidth, 'x_norm');
  steps.push(makeMlpStep(4, p));

  const branchBottom = Math.max(attnResult.bottom, mlpResult.bottom) + GROUP_GAP;

  // Parallel sum + residual add
  const sumGrp = startGroup(g, STEP_GROUPS.res1, 5);
  const sumHeaderBottom = stepHeader(sumGrp, cx, branchBottom, 5, 'Parallel Sum + Residual', 'x = x + attn_out + mlp_out', COLORS.residual.fill, COLORS.residual.stroke);
  const sumCy = sumHeaderBottom + BOX_TO_ROW_GAP + VEC_H / 2;
  opCircle(sumGrp, cx, sumCy, '⊕', COLORS.residual.stroke);
  arrowH(sumGrp, leftCx + 50, cx - 15, sumCy, COLORS.attn.stroke);
  arrowH(sumGrp, rightCx - 50, cx + 15, sumCy, COLORS.mlp.stroke);

  // Residual bypass from input around both branches (run on the left to avoid the right MLP column)
  drawResidualPath(sumGrp, cx - SEQ_W / 2 - 4, inputBottom - 30, cx - 14, sumCy, { scaleAlpha: false, side: 'left' });

  const outCy = sumCy + VEC_H / 2 + ROW_EQ_GAP + VEC_H / 2;
  drawSmallVector(sumGrp, cx, outCy, 'out', `[B, S, ${dModel}]`, COLORS.output.fill, COLORS.output.stroke, 140);
  arrowDown(sumGrp, cx, sumCy + 14, outCy - VEC_H / 2, COLORS.residual.stroke);
  steps.push(makeResStep(5, 1, p, 'x = x + attn_out + mlp_out'));

  y = outCy + VEC_H / 2 + GROUP_GAP;
  const outputBottom = drawOutputStep(g, cx, y, 6, p);
  steps.push(makeOutputStep(6, p));

  return { steps, y: outputBottom };
}

function renderSandwichNorm(g: Gsel, cx: number, y: number, p: BlockParams): RenderResult {
  const steps: BlockStep[] = [];

  const inputBottom = drawInputStep(g, cx, y, 1, p);
  steps.push(makeInputStep(1, p));
  y = inputBottom + GROUP_GAP;

  const attnStartY = inputBottom - 30;
  const attnResult = drawAttentionSubLayer(g, cx, y, 2, p, true, attnStartY);
  steps.push(makeNormStep(2, `${p.normType} (pre-attn)`, 'norm1', p));
  steps.push(makeAttnStep(3, p));
  y = attnResult.bottom + GROUP_GAP;

  const res1Bottom = drawResidualAdd(g, cx, y, 4, STEP_GROUPS.res1, 'x1 = x + Norm(attn_out)', 'Residual Add 1', attnResult, p.dModel, {
    extraNorm: p.normType,
  });
  steps.push(makeNormStep(4, `${p.normType} (post-attn)`, 'norm1', p));
  steps.push(makeResStep(5, 1, p, 'x1 = x + Norm(attn_out)'));
  y = res1Bottom + GROUP_GAP;

  const mlpStartY = res1Bottom - 30;
  const mlpResult = drawMlpSubLayer(g, cx, y, 6, p, true, mlpStartY);
  steps.push(makeNormStep(6, `${p.normType} (pre-FFN)`, 'norm2', p));
  steps.push(makeMlpStep(7, p));
  y = mlpResult.bottom + GROUP_GAP;

  const res2Bottom = drawResidualAdd(g, cx, y, 8, STEP_GROUPS.res2, 'out = x1 + Norm(mlp_out)', 'Residual Add 2', mlpResult, p.dModel, {
    extraNorm: p.normType,
  });
  steps.push(makeNormStep(8, `${p.normType} (post-FFN)`, 'norm2', p));
  steps.push(makeResStep(9, 2, p, 'out = x1 + Norm(mlp_out)'));
  y = res2Bottom + GROUP_GAP;

  const outputBottom = drawOutputStep(g, cx, y, 10, p);
  steps.push(makeOutputStep(10, p));

  return { steps, y: outputBottom };
}

function renderDeepNorm(g: Gsel, cx: number, y: number, p: BlockParams): RenderResult {
  const steps: BlockStep[] = [];

  const inputBottom = drawInputStep(g, cx, y, 1, p);
  steps.push(makeInputStep(1, p));
  y = inputBottom + GROUP_GAP;

  const attnStartY = inputBottom - 30;
  const attnResult = drawAttentionSubLayer(g, cx, y, 2, p, true, attnStartY);
  steps.push(makeNormStep(2, `${p.normType} (pre-attn)`, 'norm1', p));
  steps.push(makeAttnStep(3, p));
  y = attnResult.bottom + GROUP_GAP;

  const res1Bottom = drawResidualAdd(g, cx, y, 4, STEP_GROUPS.res1, `x1 = ${ALPHA}·x + attn_out`, 'Residual Add 1', attnResult, p.dModel, {
    scaleAlpha: true,
  });
  steps.push(makeResStep(4, 1, p, `x1 = ${ALPHA}·x + attn_out`));
  y = res1Bottom + GROUP_GAP;

  const mlpStartY = res1Bottom - 10;
  const mlpResult = drawMlpSubLayer(g, cx, y, 5, p, true, mlpStartY);
  steps.push(makeNormStep(5, `${p.normType} (pre-FFN)`, 'norm2', p));
  steps.push(makeMlpStep(6, p));
  y = mlpResult.bottom + GROUP_GAP;

  const res2Bottom = drawResidualAdd(g, cx, y, 7, STEP_GROUPS.res2, `out = ${ALPHA}·x1 + mlp_out`, 'Residual Add 2', mlpResult, p.dModel, {
    scaleAlpha: true,
  });
  steps.push(makeResStep(7, 2, p, `out = ${ALPHA}·x1 + mlp_out`));
  y = res2Bottom + GROUP_GAP;

  const outputBottom = drawOutputStep(g, cx, y, 8, p);
  steps.push(makeOutputStep(8, p));

  return { steps, y: outputBottom };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Step metadata builders
// ═══════════════════════════════════════════════════════════════════════════════

function makeInputStep(id: number, p: BlockParams): BlockStep {
  return {
    id,
    label: 'Input hidden states',
    shortLabel: 'Input',
    formula: `x ∈ ℝ^(B×S×${p.dModel})`,
    explanation: 'The transformer block receives hidden states from the previous layer, one vector per token position.',
    code: { title: 'Input', lines: [`x = previous_layer_output  # [B, S, ${p.dModel}]`] },
    svgGroup: STEP_GROUPS.input,
    color: COLORS.input.stroke,
    fill: COLORS.input.fill,
  };
}

function makeNormStep(id: number, label: string, group: string, p: BlockParams): BlockStep {
  const params = p.normType === 'LayerNorm' ? p.dModel * 2 : p.dModel;
  return {
    id,
    label,
    shortLabel: label,
    formula: p.normType === 'LayerNorm' ? 'y = (x - μ) / (σ + ε) · γ + β' : 'y = x / RMS(x) · γ',
    explanation:
      p.normType === 'LayerNorm'
        ? 'LayerNorm normalizes across the hidden dimension and learns affine gain (γ) and bias (β) parameters.'
        : 'RMSNorm normalizes by the root-mean-square of the hidden dimension and learns only a gain parameter.',
    code: {
      title: p.normType,
      lines: [
        p.normType === 'LayerNorm'
          ? `self.norm = nn.LayerNorm(${p.dModel})  # ${fmtNum(params)} params`
          : `self.norm = RMSNorm(${p.dModel})       # ${fmtNum(params)} params`,
      ],
    },
    svgGroup: group,
    color: COLORS.norm.stroke,
    fill: COLORS.norm.fill,
  };
}

function makeAttnStep(id: number, p: BlockParams): BlockStep {
  const isMHA = p.attentionType === 'mha';
  const isGQA = p.attentionType === 'gqa';
  const desc = isMHA
    ? `Multi-Head Attention splits Q, K, V into ${p.nHeads} independent heads (d_head=${p.dHead}), computes scaled dot-product attention, and projects back with W_o.`
    : isGQA
    ? `Grouped-Query Attention uses ${p.nHeads} query heads but only ${p.nKVHeads} shared K/V heads, reducing KV-cache memory.`
    : `Multi-Query Attention shares a single K/V head across all ${p.nHeads} query heads.`;
  return {
    id,
    label: `${p.attentionType.toUpperCase()} Attention`,
    shortLabel: 'Attention',
    formula: 'A = softmax(Q @ K^T / √d_head) @ V · W_o',
    explanation: desc,
    code: {
      title: 'Attention',
      lines: [
        `Q = x @ W_q   # [B, S, ${p.dModel}]`,
        `K = x @ W_k   # [B, S, ${p.dHead * p.nKVHeads}]`,
        `V = x @ W_v   # [B, S, ${p.dHead * p.nKVHeads}]`,
        `scores = Q @ K^T / sqrt(${p.dHead})`,
        `A = softmax(scores, dim=-1) @ V`,
        `attn_out = A @ W_o  # [B, S, ${p.dModel}]`,
      ],
    },
    svgGroup: STEP_GROUPS.attn,
    color: COLORS.attn.stroke,
    fill: COLORS.attn.fill,
  };
}

function makeMlpStep(id: number, p: BlockParams): BlockStep {
  const isGated = p.mlpVariant === 'swiglu' || p.mlpVariant === 'geglu';
  const formula = isGated
    ? 'mlp_out = (act(x @ W_gate) ⊙ (x @ W_up)) @ W_down'
    : `mlp_out = ${p.activation}(x @ W_up) @ W_down`;
  const explanation = isGated
    ? `The ${p.mlpVariant.toUpperCase()} FFN uses a gated branch: one projection controls the gate, another provides the up-projection, and their element-wise product is projected back down.`
    : `The standard FFN expands the hidden dimension from ${p.dModel} to ${p.dFf}, applies ${p.activation}, then projects back.`;
  return {
    id,
    label: `${p.mlpVariant.toUpperCase()} Feed-Forward Network`,
    shortLabel: 'FFN',
    formula,
    explanation,
    code: {
      title: 'FFN',
      lines: isGated
        ? [
            `gate = ${p.mlpVariant === 'swiglu' ? 'SiLU' : 'GELU'}(x @ W_gate)  # [B, S, ${p.dFf}]`,
            `up   = x @ W_up    # [B, S, ${p.dFf}]`,
            `gated = gate * up`,
            `mlp_out = gated @ W_down  # [B, S, ${p.dModel}]`,
          ]
        : [
            `up = ${p.activation}(x @ W_up)  # [B, S, ${p.dFf}]`,
            `mlp_out = up @ W_down  # [B, S, ${p.dModel}]`,
          ],
    },
    svgGroup: STEP_GROUPS.mlp,
    color: COLORS.mlp.stroke,
    fill: COLORS.mlp.fill,
  };
}

function makeResStep(
  id: number,
  idx: 1 | 2,
  p: BlockParams,
  formula?: string
): BlockStep {
  const label = idx === 1 ? 'Residual Connection 1' : 'Residual Connection 2';
  const defaultFormula = idx === 1 ? 'x1 = x + sublayer(x)' : 'out = x1 + sublayer(x1)';
  const usedFormula = formula || defaultFormula;
  return {
    id,
    label,
    shortLabel: `Residual ${idx}`,
    formula: usedFormula,
    explanation:
      'Residual connections add the sub-layer input back to its output, creating a shortcut path that preserves gradients through deep stacks.',
    code: { title: 'Residual Add', lines: [`x = x + sublayer_out  # shape [B, S, ${p.dModel}]`] },
    svgGroup: idx === 1 ? STEP_GROUPS.res1 : STEP_GROUPS.res2,
    color: COLORS.residual.stroke,
    fill: COLORS.residual.fill,
  };
}

function makeOutputStep(id: number, p: BlockParams): BlockStep {
  return {
    id,
    label: 'Output hidden states',
    shortLabel: 'Output',
    formula: `out ∈ ℝ^(B×S×${p.dModel})`,
    explanation: 'The block output has the same shape as its input and is passed to the next transformer block or the final language modeling head.',
    code: { title: 'Output', lines: [`return out  # [B, S, ${p.dModel}]`] },
    svgGroup: STEP_GROUPS.output,
    color: COLORS.output.stroke,
    fill: COLORS.output.fill,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Parameter / FLOP math
// ═══════════════════════════════════════════════════════════════════════════════

function computeMetrics(p: BlockParams) {
  const attnParams =
    p.attentionType === 'mha'
      ? p.dModel * p.dModel * 4
      : p.dModel * p.dModel + p.dModel * p.dHead * p.nKVHeads * 2 + p.dModel * p.dModel;

  const mlpParams = p.mlpVariant === 'standard' ? p.dModel * p.dFf * 2 : p.dModel * p.dFf * 3;

  const normParamsPerNorm = p.normType === 'LayerNorm' ? p.dModel * 2 : p.dModel;
  const nNorms = p.variant === 'sandwich-norm' ? 4 : p.variant === 'parallel' ? 1 : 2;
  const normParams = normParamsPerNorm * nNorms;
  const totalParams = attnParams + mlpParams + normParams;

  const qkvFlops =
    p.attentionType === 'mha'
      ? 6 * p.dModel * p.dModel * p.seqLen
      : (2 * p.dModel * p.dModel + 4 * p.dModel * p.dHead * p.nKVHeads) * p.seqLen;
  const attnFlops = 2 * p.seqLen * p.seqLen * p.dModel;
  const mlpFlops = p.mlpVariant === 'standard' ? 4 * p.dModel * p.dFf * p.seqLen : 6 * p.dModel * p.dFf * p.seqLen;
  const flopsPerLayer = qkvFlops + attnFlops + mlpFlops;

  return { attnParams, mlpParams, normParams, totalParams, flopsPerLayer };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main entry
// ═══════════════════════════════════════════════════════════════════════════════

export function renderTransformerBlockDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: import('../../graph/types').ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const p: BlockParams = {
    dModel: Number(params.d_model) || 512,
    nHeads: Number(params.n_heads) || 8,
    seqLen: Number(params.seq_len) || 128,
    dFf: Number(params.d_ff) || 2048,
    activation: String(params.activation || 'gelu'),
    normType: String(params.norm_type || 'LayerNorm'),
    variant: String(params.variant || 'pre-norm'),
    attentionType: String(params.attention_type || 'mha'),
    mlpVariant: String(params.mlp_variant || 'standard'),
    dHead: 0,
    nKVHeads: 0,
  };
  p.dHead = Math.floor(p.dModel / p.nHeads);
  p.nKVHeads =
    p.attentionType === 'mqa' ? 1 : p.attentionType === 'gqa' ? Math.max(1, Math.floor(p.nHeads / 4)) : p.nHeads;

  const root = g as unknown as Gsel;
  let y = 28;

  // Title
  lbl(root, CX, y, 'Transformer Block', { size: 18, weight: '700', color: COLORS.text });
  y += 20;
  lbl(
    root,
    CX,
    y,
    `${p.variant} · ${p.attentionType.toUpperCase()} · ${p.mlpVariant.toUpperCase()} · ${p.normType} · d_model=${p.dModel} · n_heads=${p.nHeads} · seq_len=${p.seqLen} · d_ff=${p.dFf}`,
    { size: 11, color: COLORS.muted }
  );
  y += 26;

  // Param summary
  y = drawParamSummary(root, CX, y, p);
  y += 14;

  // Variant-specific diagram
  let result: RenderResult;
  switch (p.variant) {
    case 'post-norm':
      result = renderPostNorm(root, CX, y, p);
      break;
    case 'parallel':
      result = renderParallel(root, CX, y, p);
      break;
    case 'sandwich-norm':
      result = renderSandwichNorm(root, CX, y, p);
      break;
    case 'deepnorm':
      result = renderDeepNorm(root, CX, y, p);
      break;
    case 'pre-norm':
    default:
      result = renderPreNorm(root, CX, y, p);
      break;
  }

  let footerY = result.y + 18;

  // Parameter / FLOP summary
  const metrics = computeMetrics(p);
  lbl(
    root,
    CX,
    footerY + 14,
    `Params: ${fmtNum(metrics.totalParams)} (attn ${fmtNum(metrics.attnParams)} + mlp ${fmtNum(metrics.mlpParams)} + norm ${fmtNum(metrics.normParams)}) · ~${fmtNum(metrics.flopsPerLayer)} FLOPs/layer`,
    { size: 11, color: COLORS.muted, font: 'monospace' }
  );
  footerY += 34;

  // Explanations
  const insightText = insightForVariant(p);
  const perfText = perfForVariant(p, metrics);
  footerY = drawExplanation(g, 80, footerY, W - 160, insightText, 'insight');
  footerY = drawExplanation(g, 80, footerY, W - 160, perfText, 'perf');
  footerY += 12;

  // Cross-links
  drawComponentLink(g, CX - 130, footerY, 120, 32, 'attention', 'View Attention ↗', {
    fill: COLORS.attn.fill,
    stroke: COLORS.attn.stroke,
  });
  drawComponentLink(g, CX + 10, footerY, 120, 32, 'mlp', 'View MLP ↗', {
    fill: COLORS.mlp.fill,
    stroke: COLORS.mlp.stroke,
  });
  footerY += 46;

  // Compact forward-pass code annotation
  const codeLines = buildCodeLines(p);
  footerY = drawCodeAnnotation(
    g,
    80,
    footerY,
    W - 160,
    `Transformer Block — ${p.variant.toUpperCase().replace(/-/g, ' ')}`,
    [`Params: ${fmtNum(metrics.totalParams)} · ~${fmtNum(metrics.flopsPerLayer)} FLOPs/layer`],
    codeLines
  );

  return { width: W, height: footerY + 24, steps: result.steps };
}

function insightForVariant(p: BlockParams): string {
  switch (p.variant) {
    case 'post-norm':
      return 'Post-norm places normalization after the residual addition, matching the original Transformer design. It can be harder to train at great depth but keeps the residual path clean.';
    case 'parallel':
      return 'Parallel transformer blocks run attention and FFN on the same normalized input and sum their outputs, reducing serial depth and improving throughput at the cost of more memory traffic.';
    case 'sandwich-norm':
      return 'Sandwich-norm adds an extra normalization after each sub-layer, giving stronger signal stabilization for very wide or deep models.';
    case 'deepnorm':
      return `DeepNorm scales the residual branch by α=${ALPHA} before the addition, which enables stable training of extremely deep networks (hundreds of layers).`;
    case 'pre-norm':
    default:
      return 'Pre-norm stabilizes training by normalizing before each sub-layer; the residual path remains unnormalized, making deep stacks easier to optimize.';
  }
}

function perfForVariant(p: BlockParams, metrics: ReturnType<typeof computeMetrics>): string {
  const attnNote =
    p.attentionType === 'mha'
      ? 'MHA keeps full K/V heads, maximizing expressiveness but increasing KV-cache size.'
      : p.attentionType === 'gqa'
      ? `GQA reduces KV-cache memory by sharing K/V across query groups (${p.nHeads} → ${p.nKVHeads} heads).`
      : 'MQA uses a single K/V head, minimizing KV-cache memory at some cost to quality.';
  const mlpNote =
    p.mlpVariant === 'standard'
      ? 'Standard FFN uses two matrices.'
      : `${p.mlpVariant.toUpperCase()} uses three matrices (gate + up + down), trading extra parameters for better empirical quality.`;
  const normNote = p.normType === 'LayerNorm' ? 'LayerNorm has 2× d_model params per norm.' : 'RMSNorm has 1× d_model params per norm.';
  return `${attnNote} ${mlpNote} ${normNote} This block costs ~${fmtNum(metrics.flopsPerLayer)} FLOPs per layer.`;
}

function buildCodeLines(p: BlockParams): string[] {
  const normCtor = p.normType === 'LayerNorm' ? `nn.LayerNorm(${p.dModel})` : `RMSNorm(${p.dModel})`;
  const isGated = p.mlpVariant === 'swiglu' || p.mlpVariant === 'geglu';

  const lines: string[] = [
    `self.norm1 = ${normCtor}`,
    `self.attn = ${p.attentionType.toUpperCase()}(d_model=${p.dModel}, n_heads=${p.nHeads})`,
    p.variant === 'parallel' ? '' : `self.norm2 = ${normCtor}`,
    isGated
      ? `self.mlp = ${p.mlpVariant.toUpperCase()}(d_model=${p.dModel}, d_ff=${p.dFf})`
      : `self.mlp = MLP(d_model=${p.dModel}, d_ff=${p.dFf}, activation='${p.activation}')`,
    '',
    'def forward(self, x):',
  ];

  switch (p.variant) {
    case 'post-norm':
      lines.push(`    x1 = x + self.attn(x)`, `    x1 = self.norm1(x1)`);
      lines.push(`    out = x1 + self.mlp(x1)`, `    out = self.norm2(out)`);
      break;
    case 'parallel':
      lines.push(`    n = self.norm1(x)`);
      lines.push(`    out = x + self.attn(n) + self.mlp(n)`);
      break;
    case 'sandwich-norm':
      lines.push(`    x1 = x + self.norm1(self.attn(self.norm1(x)))`);
      lines.push(`    out = x1 + self.norm2(self.mlp(self.norm2(x1)))`);
      break;
    case 'deepnorm':
      lines.push(`    x1 = ${ALPHA} * x + self.attn(self.norm1(x))`);
      lines.push(`    out = ${ALPHA} * x1 + self.mlp(self.norm2(x1))`);
      break;
    case 'pre-norm':
    default:
      lines.push(`    x1 = x + self.attn(self.norm1(x))`);
      lines.push(`    out = x1 + self.mlp(self.norm2(x1))`);
      break;
  }
  lines.push('    return out  # [B, S, D]');
  return lines.filter((l) => l !== '');
}
